parameters.jsCode:
const item = $input.item.json;

// Parse AI response - handle both direct JSON and wrapped response
let screeningResult = {};
try {
  const rawText = item.output || item.response || item.text || '{}';
  const cleaned = rawText.replace(/```json|```/g, '').trim();
  screeningResult = JSON.parse(cleaned);
} catch (e) {
  screeningResult = {
    screeningScore: 50,
    qualificationStatus: 'maybe',
    detectedExperience: 'unknown',
    detectedSkills: [],
    redFlags: [],
    extractedJobRole: item.detectedRole || 'general',
    recommendedAction: 'request_more_info',
    personalizedReply: `Hi ${item.candidateName}, thank you for reaching out! We received your message and our team will review your application shortly. We'll get back to you within 24 hours.`
  };
}

return {
  json: {
    ...item,
    ...screeningResult,
    screeningTimestamp: new Date().toISOString(),
    isQualified: screeningResult.screeningScore >= 60,
    shouldSchedule: screeningResult.recommendedAction === 'schedule_interview'
  }
};

